using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using CCSwitchUpdater;
class RouteTests {
 class Fake:HttpMessageHandler {
  readonly Func<HttpRequestMessage,HttpResponseMessage> response;
  public Fake(Func<HttpRequestMessage,HttpResponseMessage> f){response=f;}
  protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken t){t.ThrowIfCancellationRequested();var x=response(r);x.RequestMessage=r;return Task.FromResult(x);}
 }
 static int passed,failed;static string json;
 static void Assert(bool b,string why){if(!b)throw new Exception(why);}
 static void Test(string name,Action a){try{a();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static HttpResponseMessage R(int code,string text){return new HttpResponseMessage((HttpStatusCode)code){Content=new StringContent(text)};}
 static string Row="<li><a href=\"/farion1231/cc-switch/releases/download/v3.20.3/CC-Switch-v3.20.3-Windows-Portable.zip\">x64</a><span>sha256:ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad</span></li>";
 static HttpResponseMessage Page(HttpRequestMessage r){if(r.RequestUri.AbsolutePath.EndsWith("/latest")){var x=R(302,"");x.Headers.Location=new Uri("/farion1231/cc-switch/releases/tag/v3.20.3",UriKind.Relative);return x;}return R(200,r.RequestUri.AbsolutePath.Contains("expanded_assets")?Row:"release page");}
 static Release Release(){return new Release{DownloadUrl="https://github.com/farion1231/cc-switch/releases/download/v3.20.3/CC-Switch-v3.20.3-Windows-Portable.zip",Digest="sha256:ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",Size=0};}
 static string Destination(){return Path.Combine(Path.GetTempPath(),"ccswitch-route-"+Guid.NewGuid().ToString("N")+".zip");}
 static int Main(string[] args){json=File.ReadAllText(args[0]);
  Test("API 403 automatically obtains official web metadata with bound digest",delegate{int api=0,web=0;var u=new UpdateRoutes(new NetworkSettings(),new NetworkCooldown(),null,s=>new Fake(r=>{if(r.RequestUri.Host=="api.github.com"){api++;var e=R(403,"{}");e.Headers.Add("X-RateLimit-Remaining","0");e.Headers.Add("Retry-After","120");return e;}web++;return Page(r);}));var result=u.GetLatestAsync("x64",CancellationToken.None).GetAwaiter().GetResult();Assert(api==1 && web==3,"wrong API/web count");Assert(result.Tag=="v3.20.3" && result.Digest==Release().Digest,"wrong release");});
  Test("existing API cooldown skips API but still succeeds via official web",delegate{var gate=new NetworkCooldown();gate.Record(new GitHubNetworkException("primary","wait",DateTimeOffset.UtcNow.AddHours(1)));var u=new UpdateRoutes(new NetworkSettings(),gate,null,s=>new Fake(r=>{Assert(r.RequestUri.Host!="api.github.com","API contacted during wait");return Page(r);}));Assert(u.GetLatestAsync("x64",CancellationToken.None).GetAwaiter().GetResult().Tag=="v3.20.3","web skipped");});
  Test("broken system connection automatically tries direct official connection",delegate{int direct=0;var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{if(s.Mode=="system")throw new HttpRequestException("proxy unavailable");direct++;return R(200,json);}));Assert(u.GetLatestAsync("x64",CancellationToken.None).GetAwaiter().GetResult().Tag=="v3.20.1" && direct==1,"direct not attempted");});
  Test("web redirect cannot leave official release path",delegate{int count=0;using(var h=new Fake(r=>{count++;var e=R(302,"");e.Headers.Location=new Uri("https://evil.example/steal");return e;})){try{GitHubWebFallback.GetLatestAsync(new NetworkSettings(),"x64",CancellationToken.None,h).GetAwaiter().GetResult();throw new Exception("untrusted redirect accepted");}catch(InvalidDataException){}Assert(count==1,"contacted untrusted host");}});
  Test("API cancellation does not try other routes",delegate{int calls=0;var c=new CancellationTokenSource();c.Cancel();var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{calls++;return R(200,json);}));try{u.GetLatestAsync("x64",c.Token).GetAwaiter().GetResult();throw new Exception("not canceled");}catch(OperationCanceledException){}Assert(calls==0,"sent canceled request");});
  Test("official direct attachment download works during API cooldown",delegate{var gate=new NetworkCooldown();gate.Record(new GitHubNetworkException("primary","wait",DateTimeOffset.UtcNow.AddHours(1)));int calls=0;var u=new UpdateRoutes(new NetworkSettings(),gate,null,s=>new Fake(r=>{calls++;if(s.Mode=="system")throw new HttpRequestException("proxy down");return R(200,"abc");}));var release=Release();string file=Destination();u.DownloadAsync(release,file,null,CancellationToken.None).GetAwaiter().GetResult();Assert(File.ReadAllText(file)=="abc" && release.Size==3 && calls==2,"direct failed");});
  Test("official failures automatically switch to proxy download with official hash",delegate{var hosts=new List<string>();var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{hosts.Add(r.RequestUri.Host);return r.RequestUri.Host=="gh-proxy.com"?R(200,"abc"):R(502,"failed");}));var release=Release();string file=Destination();u.DownloadAsync(release,file,null,CancellationToken.None).GetAwaiter().GetResult();Assert(File.ReadAllText(file)=="abc" && hosts.Contains("gh-proxy.com"),"proxy not tried");});
  Test("wrong proxy hash is discarded and next proxy can succeed",delegate{var hosts=new List<string>();var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{hosts.Add(r.RequestUri.Host);if(r.RequestUri.Host=="gh-proxy.com")return R(200,"bad");if(r.RequestUri.Host=="ghfast.top")return R(200,"abc");return R(502,"");}));var release=Release();string file=Destination();u.DownloadAsync(release,file,null,CancellationToken.None).GetAwaiter().GetResult();Assert(hosts.Contains("ghfast.top") && File.ReadAllText(file)=="abc","bad proxy accepted or next not tried");});
  Test("all failed hashes leave no installable file and no learned size",delegate{var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>R(200,"bad")));var release=Release();string file=Destination();try{u.DownloadAsync(release,file,null,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("bad hash accepted");}catch(IOException){}Assert(!File.Exists(file) && release.Size==0,"partial/bad file retained");});
  Test("proxy switch can be disabled and no third-party host contacted",delegate{var settings=new NetworkSettings{AllowDownloadMirrors=false};var u=new UpdateRoutes(settings,null,null,s=>new Fake(r=>{Assert(r.RequestUri.Host=="github.com","proxy contacted");return R(502,"");}));try{u.DownloadAsync(Release(),Destination(),null,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("expected failure");}catch(IOException){}});
  Test("existing destination is preserved",delegate{string file=Destination();File.WriteAllText(file,"keep");var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{throw new Exception("request sent for existing target");}));try{u.DownloadAsync(Release(),file,null,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("overwrote existing file");}catch(IOException){}Assert(File.ReadAllText(file)=="keep","existing file damaged");});
  Test("proxy redirect cannot escape mirror whitelist",delegate{int evil=0;var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{if(r.RequestUri.Host=="evil.example")evil++;if(r.RequestUri.Host=="github.com")return R(502,"");var e=R(302,"");e.Headers.Location=new Uri("https://evil.example/bad.zip");return e;}));try{u.DownloadAsync(Release(),Destination(),null,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("accepted redirect");}catch(IOException){}Assert(evil==0,"untrusted host contacted");});
  Test("truncated file is discarded before trying the next route",delegate {var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{var x=R(200,"abc");if(s.Mode=="system")x.Content.Headers.ContentLength=10;return x;}));string file=Destination();var release=Release();u.DownloadAsync(release,file,null,CancellationToken.None).GetAwaiter().GetResult();Assert(File.ReadAllText(file)=="abc" && release.Size==3,"truncated response kept");});
  Test("canceled download never tries a proxy",delegate {int calls=0;var cancel=new CancellationTokenSource();cancel.Cancel();var u=new UpdateRoutes(new NetworkSettings(),null,null,s=>new Fake(r=>{calls++;return R(200,"abc");}));try{u.DownloadAsync(Release(),Destination(),null,cancel.Token).GetAwaiter().GetResult();throw new Exception("cancellation ignored");}catch(OperationCanceledException){}Assert(calls==0,"request after cancel");});
  Test("mirror origin cannot be chosen from arbitrary user URL",delegate {Assert(!GitHubHttp.IsMirrorUrl("https://evil.example/"+Release().DownloadUrl,"https://evil.example/"),"unknown mirror allowed");});
  Console.WriteLine("RESULT "+passed+" passed, "+failed+" failed");return failed==0?0:1;
 }
}
